# Meeting 5, parts 3 to 5: liquidity, leverage and efficiency, one ratio at a time on Noa's two years (figures in content_l5o.py).
# Every family: one ratio per slide (ONE), the rule with every definition and its fraction, a live sheet for both years, questions
# beside the data from easy to hard, and a tool card.


def RULE(sid, title, defs, fracs, note=None, tag='הגדרה והדגמה'):
    """The definitions of a family, revealed one by one, then each ratio drawn as a fraction with Noa's 2027 numbers."""
    k = len(defs)
    body = f'<div class="row eq{k} top">' + ''.join(DEF(*d, n=i + 1) if len(d) == 3 else DEF(d[0], d[1], d[2], n=i + 1, trm=d[3]) for i, d in enumerate(defs)) + '</div>'
    if MODE == 'deck':
        body += f'<div class="row eq{k} top fr3row">' + ''.join(ST(k + i + 1, FRAC(*f), cls='card') for i, f in enumerate(fracs)) + '</div>'
    if note: body += BAND('note', note, 2 * k + 1)
    S(sid, title, title, body, kick=f'חלק {CUR[0]} · {tag}')


def RSHEET(rows, ratios, widths=(250, 125, 125, 340)):
    """A ratio sheet: Noa's figures in rows 2.., the ratios below them for both years, and how each one is computed in column D."""
    hr = len(rows) + 2

    def extra(d, g, f, st, sol, steps):
        d[f'A{hr}'] = 'יחס'; d[f'B{hr}'] = 'שנת 2026'; d[f'C{hr}'] = 'שנת 2027'; d[f'D{hr}'] = 'איך מחשבים'
        for c in 'ABCD': st[f'{c}{hr}'] = {'fill': '#fff0c2', 'b': True, 'al': 'center' if c in 'BC' else 'right'}
        for i, (n, fx, fm, how) in enumerate(ratios):
            r = hr + 1 + i; d[f'A{r}'] = n; d[f'D{r}'] = how
            cells = {}
            for c in 'BC':
                sol[f'{c}{r}'] = fx.format(c=c); f[f'{c}{r}'] = fm; st[f'{c}{r}'] = {'al': 'center'}; cells[f'{c}{r}'] = sol[f'{c}{r}']
            steps.append(dict(cells=cells, note=f'<b>{n}:</b> {how}: {XL(fx.format(c="B"))} ל-2026, וכך גם ל-2027.', sel=f'B{r}'))
    sp = _bigsheet(['נתון', 'שנת 2026', 'שנת 2027'], rows, [], list(widths), None, lambda i, r: '', extra)
    sp['steps'] = [x for x in sp['steps'] if x['cells']]
    return sp


def FL3(items):
    """The formulas of a tool card as a compact list: the name, then what is on top and what is below."""
    return '<div class="fl3">' + ''.join(f'<div class="fl-r"><b>{TX(n)}</b><span>{TX(t)}</span><i>÷</i><span>{TX(b)}</span></div>' for t, b, n in items) + '</div>'


_nr = lambda *keys: [(lab, NV[k][0], NV[k][1]) for k, lab in keys]
_side = lambda rows, hl=None: _dt(['יחס', '2026', '2027'], rows, hl, 'mdt')

