# ---------------------------------------------------------------- the aggregate: the cash cycle on a timeline
_d1, _d2, _d3 = RT['dio'][1], RT['dso'][1], RT['dpo'][1]
_sc = lambda x: x / 30 * 100
if MODE == 'deck':
    _tl = ('<div class="ccl">'
           + ST(1, f'<div class="cc-bar inv" style="right:0;width:{_sc(_d1):.1f}%"><b>{TX("המלאי במחסן")}</b><span class="n">{f1(_d1)}</span></div>', cls='cc-r r1')
           + ST(2, f'<div class="cc-bar cus" style="right:{_sc(_d1):.1f}%;width:{_sc(_d2):.1f}%"><b>{TX("הלקוח משלם")}</b><span class="n">{f1(_d2)}</span></div>', cls='cc-r r1')
           + ST(3, f'<div class="cc-bar sup" style="right:0;width:{_sc(_d3):.1f}%"><b>{TX("נועה משלמת לספק")}</b><span class="n">{f1(_d3)}</span></div>', cls='cc-r r2')
           + ST(4, f'<div class="cc-bar gap" style="right:{_sc(_d3):.1f}%;width:{_sc(_d1 + _d2 - _d3):.1f}%"><b>{TX("מחזור המזומנים")}</b><span class="n">{f1(RT["ccc"][1])}</span></div>', cls='cc-r r3')
           + '<div class="cc-ax">' + ''.join(f'<span style="right:{_sc(x):.1f}%"><i class="n">{x}</i></span>' for x in range(0, 31, 5)) + '</div>'
           + f'<div class="cc-cap">{TX("ימים מהיום שהפולים הגיעו למחסן")}</div></div>')
else:
    _tl = TABLE(['שלב', 'ימים, 2027'], [['המלאי במחסן', f1(_d1)], ['הלקוח משלם', f1(_d2)], ['נועה משלמת לספק', f1(_d3)], ['מחזור המזומנים', f1(RT['ccc'][1])]], cls='tight')
S('s-ccc', 'מחזור המזומנים, על ציר הזמן', 'ועכשיו יחד: מחזור המזומנים של קפה נועה, 2027',
  '<div class="row g55 top"><div class="col">' + _tl + '</div><div class="col">'
  + DEF('מחזור המזומנים (Cash conversion cycle)', 'ימי מלאי ועוד ימי לקוחות, פחות ימי ספקים: כמה ימים העסק צריך לממן בעצמו, מהתשלום לספק ועד שהכסף של הלקוח בקופה.', '16.2 ועוד 12.2, פחות 18.9: 9.5 ימים.', n=5, trm='ccc')
  + BAND('dg', 'מחזור קצר: הכסף חוזר מהר, ונועה צריכה מעט מימון לזמן קצר. ב-2026 המחזור היה 7.1 ימים: הוא התארך מעט, כי הקייטרינג גדל.', 6) + '</div></div>', kick='חלק 5 · מצרפים')

